inline constexpr std::size_t kDecompositionCount = sizeof(kDecompositions) / sizeof(kDecompositions[0]);
inline constexpr std::size_t kCombiningClassCount = sizeof(kCombiningClasses) / sizeof(kCombiningClasses[0]);
inline constexpr std::size_t kCompositionCount = sizeof(kCompositions) / sizeof(kCompositions[0]);
inline constexpr std::size_t kLowercaseCount = sizeof(kLowercaseMappings) / sizeof(kLowercaseMappings[0]);
inline constexpr std::size_t kUppercaseCount = sizeof(kUppercaseMappings) / sizeof(kUppercaseMappings[0]);
inline constexpr std::size_t kTitlecaseCount = sizeof(kTitlecaseMappings) / sizeof(kTitlecaseMappings[0]);

inline const Decomposition *findDecomposition(std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = kDecompositionCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kDecompositions[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kDecompositionCount && kDecompositions[low].codepoint == codepoint)
    {
        return &kDecompositions[low];
    }
    return nullptr;
}

inline std::uint8_t combiningClass(std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = kCombiningClassCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kCombiningClasses[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kCombiningClassCount && kCombiningClasses[low].codepoint == codepoint)
    {
        return kCombiningClasses[low].value;
    }
    return 0;
}

inline bool compose(std::uint32_t first, std::uint32_t second, std::uint32_t &composed)
{
    std::size_t low = 0;
    std::size_t high = kCompositionCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        const Composition &candidate = kCompositions[middle];
        if (candidate.first < first || (candidate.first == first && candidate.second < second))
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kCompositionCount && kCompositions[low].first == first && kCompositions[low].second == second)
    {
        composed = kCompositions[low].composed;
        return true;
    }
    return false;
}

inline const CaseMapping *findCaseMapping(const CaseMapping *table, std::size_t count, std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = count;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (table[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < count && table[low].codepoint == codepoint)
    {
        return &table[low];
    }
    return nullptr;
}

inline bool inRanges(const CodepointRange *ranges, std::size_t count, std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = count;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (ranges[middle].last < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    return low < count && ranges[low].first <= codepoint;
}

inline bool isWord(std::uint32_t codepoint)
{
    return inRanges(kWordRanges, sizeof(kWordRanges) / sizeof(kWordRanges[0]), codepoint);
}

inline bool isCased(std::uint32_t codepoint)
{
    return inRanges(kCasedRanges, sizeof(kCasedRanges) / sizeof(kCasedRanges[0]), codepoint);
}

inline bool isLetter(std::uint32_t codepoint)
{
    return inRanges(kLetterRanges, sizeof(kLetterRanges) / sizeof(kLetterRanges[0]), codepoint);
}

